<template>
  <div class="page-shell">
    <header class="page-header"><div><h2>岗位管理</h2><p>维护岗位归属、类型和可用状态</p></div><button class="primary-btn" @click="openCreate"><svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg>新增岗位</button></header>
    <section class="stat-grid"><div><span>岗位总数</span><strong>{{ positions.length }}</strong></div><div><span>正常岗位</span><strong>{{ activeCount }}</strong></div><div><span>涉及部门</span><strong>{{ departmentCount }}</strong></div></section>
    <section class="filter-panel"><label><span>关键字</span><input v-model.trim="keyword" placeholder="岗位名称、编号或编码" /></label><label><span>所属部门</span><select v-model="departmentFilter"><option value="">全部</option><option v-for="item in departments" :key="item.id" :value="item.id">{{ item.departmentName }}</option></select></label><label><span>岗位类型</span><select v-model="typeFilter"><option value="">全部</option><option :value="1">教学</option><option :value="2">管理</option><option :value="3">其他</option></select></label><label><span>岗位状态</span><select v-model="statusFilter"><option value="">全部</option><option :value="1">正常</option><option :value="2">停用</option></select></label><button class="ghost-btn" @click="resetFilters">重置</button></section>
    <div v-if="message.text" class="message" :class="message.type">{{ message.text }}</div>
    <section class="table-card">
      <div v-if="loading" class="state-box">正在加载岗位数据…</div><div v-else-if="filteredPositions.length === 0" class="state-box">没有符合条件的岗位</div>
      <div v-else class="table-scroll"><table><thead><tr><th>岗位名称</th><th>编号 / 编码</th><th>类型</th><th>所属部门</th><th>排序</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in filteredPositions" :key="item.id"><td><strong>{{ item.positionName }}</strong><small>{{ item.description || '暂无说明' }}</small></td><td><code>{{ item.positionNo }}</code><small>{{ item.positionCode }}</small></td><td><span class="tag">{{ typeLabel(item.positionType) }}</span></td><td>{{ departmentName(item.departmentId) }}</td><td>{{ item.sortNo }}</td><td><span class="status"><i :class="item.positionStatus === 1 ? 'on' : 'off'"></i>{{ item.positionStatus === 1 ? '正常' : '停用' }}</span></td><td><div class="row-actions"><button @click="openEdit(item)">编辑</button><button @click="toggleStatus(item)">{{ item.positionStatus === 1 ? '停用' : '恢复' }}</button></div></td></tr></tbody></table></div>
    </section>
    <teleport to="body"><div v-if="dialogOpen" class="modal-overlay" @click.self="closeDialog"><section class="modal-panel"><header class="modal-header"><div><h3>{{ editingId ? '编辑岗位' : '新增岗位' }}</h3><p>岗位编号和编码创建后不可修改</p></div><button class="icon-btn" @click="closeDialog"><svg viewBox="0 0 24 24"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><div class="modal-body"><div class="form-grid">
      <label><span>岗位编号 *</span><input v-model.trim="form.positionNo" :disabled="Boolean(editingId)" placeholder="如 POS-001" /></label><label><span>岗位编码 *</span><input v-model.trim="form.positionCode" :disabled="Boolean(editingId)" placeholder="如 TEACHER" /></label><label><span>岗位名称 *</span><input v-model.trim="form.positionName" /></label><label><span>岗位类型 *</span><select v-model="form.positionType"><option :value="1">教学</option><option :value="2">管理</option><option :value="3">其他</option></select></label><label><span>所属部门 *</span><select v-model="form.departmentId"><option :value="0" disabled>请选择</option><option v-for="item in departments" :key="item.id" :value="item.id">{{ item.departmentName }}</option></select></label><label><span>状态 *</span><select v-model="form.positionStatus"><option :value="1">正常</option><option :value="2">停用</option></select></label><label><span>排序号</span><input v-model.number="form.sortNo" type="number" min="0" /></label><label class="full"><span>岗位说明</span><textarea v-model.trim="form.description" rows="3"></textarea></label>
    </div><p v-if="formError" class="form-error">{{ formError }}</p></div><footer class="modal-footer"><button class="ghost-btn" @click="closeDialog">取消</button><button class="primary-btn" :disabled="saving" @click="save">{{ saving ? '保存中…' : '保存' }}</button></footer></section></div></teleport>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { createPosition, getDepartmentTree, getPositions, updatePosition, updatePositionStatus, type DepartmentItem, type PositionItem, type PositionStatus, type PositionType } from '../../utils/personnelApi'

const positions = ref<PositionItem[]>([])
const departments = ref<DepartmentItem[]>([])
const loading = ref(false)
const dialogOpen = ref(false)
const saving = ref(false)
const editingId = ref<number | null>(null)
const keyword = ref('')
const departmentFilter = ref<number | ''>('')
const typeFilter = ref<PositionType | ''>('')
const statusFilter = ref<PositionStatus | ''>('')
const formError = ref('')
const message = reactive({ text: '', type: 'success' as 'success' | 'error' })
const form = reactive({ positionNo: '', positionCode: '', positionName: '', positionType: 1 as PositionType, departmentId: 0, positionStatus: 1 as PositionStatus, sortNo: 0, description: '' })
const activeCount = computed(() => positions.value.filter(item => item.positionStatus === 1).length)
const departmentCount = computed(() => new Set(positions.value.map(item => item.departmentId)).size)
const filteredPositions = computed(() => positions.value.filter(item => { const text = `${item.positionName} ${item.positionNo} ${item.positionCode}`.toLowerCase(); return (!keyword.value || text.includes(keyword.value.toLowerCase())) && (departmentFilter.value === '' || item.departmentId === departmentFilter.value) && (typeFilter.value === '' || item.positionType === typeFilter.value) && (statusFilter.value === '' || item.positionStatus === statusFilter.value) }))
function flatten(items: DepartmentItem[]): DepartmentItem[] { return items.flatMap(item => [item, ...flatten(item.children || [])]) }
function errorText(error: unknown): string { return error instanceof Error ? error.message : '操作失败，请稍后重试' }
function showMessage(text: string, type: 'success' | 'error' = 'success'): void { message.text = text; message.type = type; window.setTimeout(() => { if (message.text === text) message.text = '' }, 4000) }
function typeLabel(value: number): string { return ({ 1: '教学', 2: '管理', 3: '其他' } as Record<number, string>)[value] || '未知' }
function departmentName(id: number): string { return departments.value.find(item => item.id === id)?.departmentName || '未知部门' }
async function loadData(): Promise<void> { loading.value = true; try { const [tree, page] = await Promise.all([getDepartmentTree(), getPositions({ pageNum: 1, pageSize: 500 })]); departments.value = flatten(tree); positions.value = page.records } catch (error) { showMessage(errorText(error), 'error') } finally { loading.value = false } }
function resetFilters(): void { keyword.value = ''; departmentFilter.value = ''; typeFilter.value = ''; statusFilter.value = '' }
function resetForm(): void { Object.assign(form, { positionNo: '', positionCode: '', positionName: '', positionType: 1, departmentId: 0, positionStatus: 1, sortNo: 0, description: '' }); formError.value = '' }
function openCreate(): void { resetForm(); editingId.value = null; dialogOpen.value = true }
function openEdit(item: PositionItem): void { editingId.value = item.id; Object.assign(form, { positionNo: item.positionNo, positionCode: item.positionCode, positionName: item.positionName, positionType: item.positionType, departmentId: item.departmentId, positionStatus: item.positionStatus, sortNo: item.sortNo, description: item.description || '' }); formError.value = ''; dialogOpen.value = true }
function closeDialog(): void { if (!saving.value) dialogOpen.value = false }
async function save(): Promise<void> { if (!form.positionNo || !form.positionCode || !form.positionName || !form.departmentId) { formError.value = '请填写岗位编号、编码、名称并选择所属部门'; return } saving.value = true; const common = { positionName: form.positionName, positionType: form.positionType, departmentId: form.departmentId, positionStatus: form.positionStatus, sortNo: form.sortNo, description: form.description || undefined }; try { if (editingId.value) await updatePosition(editingId.value, common); else await createPosition({ positionNo: form.positionNo, positionCode: form.positionCode, ...common }); dialogOpen.value = false; showMessage('岗位信息已保存'); await loadData() } catch (error) { formError.value = errorText(error) } finally { saving.value = false } }
async function toggleStatus(item: PositionItem): Promise<void> { const next: PositionStatus = item.positionStatus === 1 ? 2 : 1; if (!window.confirm(`确认${next === 1 ? '恢复' : '停用'}“${item.positionName}”？`)) return; try { await updatePositionStatus(item.id, next); showMessage('岗位状态已更新'); await loadData() } catch (error) { showMessage(errorText(error), 'error') } }
onMounted(loadData)
</script>

<style scoped>
.page-shell{height:100%;overflow:auto;padding:24px;color:#172033;background:transparent}.page-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}.page-header h2{margin:0;font-size:22px}.page-header p,.modal-header p{margin:5px 0 0;color:#7b8495;font-size:13px}.primary-btn,.ghost-btn{border:0;border-radius:8px;padding:9px 15px;font:inherit;font-size:13px;cursor:pointer}.primary-btn{display:inline-flex;align-items:center;gap:7px;background:#2563eb;color:#fff}.primary-btn svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2}.ghost-btn{background:#eef1f6;color:#4b5565}.primary-btn:disabled{opacity:.55}.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:14px}.stat-grid>div,.filter-panel,.table-card{background:#fff;border:1px solid #e7ebf1;border-radius:12px}.stat-grid>div{padding:16px 18px}.stat-grid span{display:block;color:#7b8495;font-size:12px}.stat-grid strong{display:block;margin-top:5px;font-size:24px}.filter-panel{display:grid;grid-template-columns:2fr repeat(3,1fr) auto;align-items:end;gap:10px;padding:15px;margin-bottom:14px}.filter-panel label,.form-grid label{display:flex;flex-direction:column;gap:6px}.filter-panel span,.form-grid span{font-size:12px;color:#687386}.filter-panel input,.filter-panel select,.form-grid input,.form-grid select,.form-grid textarea{box-sizing:border-box;width:100%;border:1px solid #dfe4ec;border-radius:8px;padding:9px 10px;background:#fff;font:inherit;font-size:13px;outline:none}.message{margin-bottom:12px;border-radius:8px;padding:10px 13px;font-size:13px}.message.success{background:#ecfdf3;color:#137a45}.message.error{background:#fff1f2;color:#b42336}.table-card{overflow:hidden}.table-scroll{overflow:auto}table{width:100%;min-width:850px;border-collapse:collapse}th,td{padding:13px 14px;border-bottom:1px solid #eef1f5;text-align:left;font-size:13px}th{background:#fafbfc;color:#687386;font-size:12px}td small{display:block;margin-top:4px;color:#9098a7}code{font-size:12px}.tag{display:inline-block;padding:3px 8px;border-radius:5px;background:#eff6ff;color:#1d4ed8}.status{display:inline-flex;align-items:center;gap:6px}.status i{width:7px;height:7px;border-radius:50%;background:#dc5b61}.status i.on{background:#22a06b}.row-actions{display:flex;gap:6px}.row-actions button{border:1px solid #dfe4ec;border-radius:7px;background:#fff;padding:6px 9px;color:#4b5565;font-size:12px;cursor:pointer}.state-box{padding:56px;text-align:center;color:#8992a2}.modal-overlay{position:fixed;inset:0;z-index:1200;display:flex;align-items:center;justify-content:center;padding:24px;background:rgba(15,23,42,.42)}.modal-panel{width:min(700px,100%);max-height:88vh;display:flex;flex-direction:column;background:#fff;border-radius:14px}.modal-header{display:flex;justify-content:space-between;padding:20px 22px;border-bottom:1px solid #eef1f5}.modal-header h3{margin:0;font-size:18px}.icon-btn{border:0;background:none;cursor:pointer}.icon-btn svg{width:20px;height:20px;fill:none;stroke:#687386;stroke-width:2}.modal-body{padding:20px 22px;overflow:auto}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.form-grid :disabled{background:#f5f6f8}.form-grid .full{grid-column:1/-1}.form-grid textarea{resize:vertical}.form-error{color:#b42336;font-size:13px}.modal-footer{display:flex;justify-content:flex-end;gap:8px;padding:15px 22px;border-top:1px solid #eef1f5}@media(max-width:900px){.filter-panel{grid-template-columns:repeat(2,1fr)}.stat-grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.form-grid .full{grid-column:auto}}
</style>
